// Made by tools/build-queries.js from queries/*.sql. Do not edit by hand.
(function (root) {
  var queries = {
  "mysql": "-- Joinscope catalogue query for MySQL 5.7+ and MariaDB 10.2+\n--\n-- Read-only: it reads the database's catalogue (information_schema), never your data.\n-- Run it on the database you want to explore, copy the one cell it returns, and paste\n-- it into Joinscope (Import, \"From a query\"). Both statements are needed: the first lets\n-- the result be longer than 1 KB.\n\nSET SESSION group_concat_max_len = 1073741824;\n\nSELECT CONCAT(\n  '{\"format\":\"joinscope-catalogue\",\"version\":1,\"dialect\":\"mysql\",\"database\":', JSON_QUOTE(DATABASE()),\n  ',\"tables\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', t.TABLE_NAME, 'rows', t.TABLE_ROWS, 'comment', t.TABLE_COMMENT, 'engine', t.ENGINE) SEPARATOR ',')\n    FROM information_schema.TABLES t\n    WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_TYPE = 'BASE TABLE'), ''),\n  '],\"columns\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', c.TABLE_NAME, 'column', c.COLUMN_NAME, 'position', c.ORDINAL_POSITION,\n      'type', c.COLUMN_TYPE, 'nullable', c.IS_NULLABLE = 'YES', 'default', c.COLUMN_DEFAULT, 'comment', c.COLUMN_COMMENT,\n      'auto', c.EXTRA LIKE '%auto_increment%', 'generated', IFNULL(c.GENERATION_EXPRESSION, '') <> '') SEPARATOR ',')\n    FROM information_schema.COLUMNS c\n    JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME AND t.TABLE_TYPE = 'BASE TABLE'\n    WHERE c.TABLE_SCHEMA = DATABASE()), ''),\n  '],\"primary_keys\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', k.TABLE_NAME, 'column', k.COLUMN_NAME, 'position', k.ORDINAL_POSITION) SEPARATOR ',')\n    FROM information_schema.KEY_COLUMN_USAGE k\n    WHERE k.TABLE_SCHEMA = DATABASE() AND k.CONSTRAINT_NAME = 'PRIMARY'), ''),\n  '],\"foreign_keys\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', k.CONSTRAINT_NAME, 'table', k.TABLE_NAME, 'column', k.COLUMN_NAME, 'position', k.ORDINAL_POSITION,\n      'ref_table', k.REFERENCED_TABLE_NAME, 'ref_column', k.REFERENCED_COLUMN_NAME,\n      'on_delete', (SELECT r.DELETE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS r\n                    WHERE r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME),\n      'on_update', (SELECT r.UPDATE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS r\n                    WHERE r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME)) SEPARATOR ',')\n    FROM information_schema.KEY_COLUMN_USAGE k\n    WHERE k.TABLE_SCHEMA = DATABASE() AND k.REFERENCED_TABLE_NAME IS NOT NULL), ''),\n  '],\"indexes\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', s.TABLE_NAME, 'name', s.INDEX_NAME, 'unique', s.NON_UNIQUE = 0, 'type', s.INDEX_TYPE,\n      'column', s.COLUMN_NAME, 'position', s.SEQ_IN_INDEX) SEPARATOR ',')\n    FROM information_schema.STATISTICS s\n    WHERE s.TABLE_SCHEMA = DATABASE() AND s.INDEX_NAME <> 'PRIMARY'), ''),\n  '],\"views\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', v.TABLE_NAME, 'sql', v.VIEW_DEFINITION) SEPARATOR ',')\n    FROM information_schema.VIEWS v\n    WHERE v.TABLE_SCHEMA = DATABASE()), ''),\n  '],\"triggers\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', g.TRIGGER_NAME, 'table', g.EVENT_OBJECT_TABLE, 'timing', g.ACTION_TIMING,\n      'event', g.EVENT_MANIPULATION, 'body', g.ACTION_STATEMENT) SEPARATOR ',')\n    FROM information_schema.TRIGGERS g\n    WHERE g.TRIGGER_SCHEMA = DATABASE()), ''),\n  ']}') AS joinscope;\n",
  "oracle": "-- Joinscope catalogue query for Oracle Database 18c+ (19c, 21c, 23ai, Autonomous Database)\n--\n-- Read-only: it reads the catalogue of the schema you are logged in as (the USER_ views),\n-- never your data. Run it, copy the one cell it returns, and paste it into Joinscope\n-- (Import, \"From a query\"). In SQL Developer, double-click the cell to see all of it.\n-- In SQL*Plus or SQLcl, run this first so the whole result is printed:\n--   SET LONG 100000000 LONGCHUNKSIZE 100000000 PAGESIZE 0 LINESIZE 32767 TRIMOUT OFF FEEDBACK OFF\n-- A long result comes out on several lines; paste them all, Joinscope joins them again.\n-- Row counts come from the optimizer statistics, so they are estimates (empty until\n-- statistics have been gathered). Defaults, index expressions and view texts are kept by\n-- Oracle as LONG values, which SQL cannot read: the three functions declared here read\n-- them. They live only while the query runs; nothing is created in your database.\n-- In SQL*Plus and SQLcl a query that declares functions ends with the / line below.\n\nWITH\n  FUNCTION js_default(t VARCHAR2, c VARCHAR2) RETURN VARCHAR2 IS\n    v LONG;\n  BEGIN\n    SELECT data_default INTO v FROM user_tab_cols WHERE table_name = t AND column_name = c;\n    RETURN SUBSTRB(v, 1, 4000);\n  END;\n  FUNCTION js_index_expression(i VARCHAR2, p NUMBER) RETURN VARCHAR2 IS\n    v LONG;\n  BEGIN\n    SELECT column_expression INTO v FROM user_ind_expressions WHERE index_name = i AND column_position = p;\n    RETURN SUBSTRB(v, 1, 4000);\n  END;\n  -- a view's whole text, up to the 32,760 bytes PL/SQL can hold (TEXT_VC stops at 4,000)\n  FUNCTION js_view_text(n VARCHAR2) RETURN CLOB IS\n    v LONG;\n    len NUMBER;\n  BEGIN\n    SELECT text_length INTO len FROM user_views WHERE view_name = n;\n    IF len > 32760 THEN\n      SELECT text_vc INTO v FROM user_views WHERE view_name = n;\n    ELSE\n      SELECT text INTO v FROM user_views WHERE view_name = n;\n    END IF;\n    RETURN TO_CLOB(v);\n  END;\nSELECT JSON_OBJECT(\n  'format' VALUE 'joinscope-catalogue',\n  'version' VALUE 1,\n  'dialect' VALUE 'oracle',\n  'database' VALUE SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA'),\n  'tables' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT('table' VALUE t.table_name, 'rows' VALUE t.num_rows, 'comment' VALUE c.comments RETURNING CLOB) RETURNING CLOB)\n    FROM user_tables t\n    LEFT JOIN user_tab_comments c ON c.table_name = t.table_name\n    WHERE t.dropped = 'NO' AND t.nested = 'NO' AND t.secondary = 'N' AND (t.iot_type IS NULL OR t.iot_type = 'IOT')\n      AND t.table_name NOT IN (SELECT mview_name FROM user_mviews)\n  ) FORMAT JSON,\n  'columns' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT(\n      'table' VALUE k.table_name, 'column' VALUE k.column_name, 'position' VALUE k.column_id,\n      'type' VALUE CASE\n        WHEN k.data_type IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') THEN k.data_type || '(' || k.char_length || ')'\n        WHEN k.data_type = 'RAW' THEN 'RAW(' || k.data_length || ')'\n        WHEN k.data_type = 'NUMBER' AND k.data_precision IS NOT NULL THEN 'NUMBER(' || k.data_precision || ',' || k.data_scale || ')'\n        WHEN k.data_type = 'NUMBER' AND k.data_scale = 0 THEN 'NUMBER(*,0)'\n        WHEN k.data_type = 'FLOAT' THEN 'FLOAT(' || k.data_precision || ')'\n        ELSE k.data_type\n      END,\n      'nullable' VALUE CASE k.nullable WHEN 'Y' THEN 'true' ELSE 'false' END FORMAT JSON,\n      'default' VALUE CASE WHEN k.default_length > 0 AND k.identity_column = 'NO' AND k.virtual_column = 'NO'\n        THEN js_default(k.table_name, k.column_name) END,\n      'auto' VALUE CASE k.identity_column WHEN 'YES' THEN 'true' ELSE 'false' END FORMAT JSON,\n      'generated' VALUE CASE k.virtual_column WHEN 'YES' THEN 'true' ELSE 'false' END FORMAT JSON,\n      'comment' VALUE cc.comments RETURNING CLOB) RETURNING CLOB)\n    FROM user_tab_cols k\n    JOIN user_tables t ON t.table_name = k.table_name\n    LEFT JOIN user_col_comments cc ON cc.table_name = k.table_name AND cc.column_name = k.column_name\n    WHERE k.hidden_column = 'NO' AND t.dropped = 'NO' AND t.nested = 'NO' AND t.secondary = 'N'\n      AND (t.iot_type IS NULL OR t.iot_type = 'IOT') AND t.table_name NOT IN (SELECT mview_name FROM user_mviews)\n  ) FORMAT JSON,\n  'primary_keys' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT('table' VALUE cc.table_name, 'column' VALUE cc.column_name, 'position' VALUE cc.position) RETURNING CLOB)\n    FROM user_constraints c\n    JOIN user_cons_columns cc ON cc.constraint_name = c.constraint_name\n    WHERE c.constraint_type = 'P' AND c.table_name NOT LIKE 'BIN$%'\n  ) FORMAT JSON,\n  'foreign_keys' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT(\n      'name' VALUE c.constraint_name, 'table' VALUE cc.table_name, 'column' VALUE cc.column_name, 'position' VALUE cc.position,\n      'ref_schema' VALUE CASE WHEN c.r_owner <> USER THEN c.r_owner END,\n      'ref_table' VALUE rc.table_name, 'ref_column' VALUE rc.column_name,\n      'on_delete' VALUE c.delete_rule, 'on_update' VALUE 'NO ACTION') RETURNING CLOB)\n    FROM user_constraints c\n    JOIN user_cons_columns cc ON cc.constraint_name = c.constraint_name\n    JOIN all_cons_columns rc ON rc.owner = c.r_owner AND rc.constraint_name = c.r_constraint_name AND rc.position = cc.position\n    WHERE c.constraint_type = 'R' AND c.table_name NOT LIKE 'BIN$%'\n  ) FORMAT JSON,\n  'indexes' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT(\n      'table' VALUE i.table_name, 'name' VALUE i.index_name,\n      'unique' VALUE CASE i.uniqueness WHEN 'UNIQUE' THEN 'true' ELSE 'false' END FORMAT JSON,\n      'type' VALUE i.index_type, 'position' VALUE ic.column_position,\n      -- a function-based index names a hidden column; the expression is what it indexes\n      'column' VALUE CASE WHEN i.index_type LIKE 'FUNCTION-BASED%' AND ic.column_name LIKE 'SYS\\_NC%$' ESCAPE '\\'\n        THEN js_index_expression(i.index_name, ic.column_position) ELSE ic.column_name END RETURNING CLOB) RETURNING CLOB)\n    FROM user_indexes i\n    JOIN user_ind_columns ic ON ic.index_name = i.index_name\n    WHERE i.index_type NOT IN ('LOB', 'IOT - TOP') AND i.table_type = 'TABLE' AND i.table_name NOT LIKE 'BIN$%'\n      AND i.index_name NOT IN (SELECT index_name FROM user_constraints WHERE constraint_type = 'P' AND index_name IS NOT NULL)\n  ) FORMAT JSON,\n  'views' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT('name' VALUE v.view_name, 'sql' VALUE js_view_text(v.view_name) RETURNING CLOB) RETURNING CLOB)\n    FROM user_views v\n  ) FORMAT JSON,\n  'triggers' VALUE (\n    SELECT JSON_ARRAYAGG(JSON_OBJECT(\n      'name' VALUE g.trigger_name, 'table' VALUE g.table_name,\n      'timing' VALUE REGEXP_SUBSTR(g.trigger_type, '^(BEFORE|AFTER|INSTEAD OF)'), 'event' VALUE g.triggering_event) RETURNING CLOB)\n    FROM user_triggers g\n    WHERE g.base_object_type = 'TABLE' AND g.table_name NOT LIKE 'BIN$%'\n  ) FORMAT JSON\n  RETURNING CLOB) AS joinscope\nFROM dual\n/\n",
  "postgres": "-- Joinscope catalogue query for PostgreSQL 12+ (also Supabase and Neon, which run PostgreSQL)\n--\n-- Read-only: it reads the database's catalogue (pg_catalog), never your data.\n-- Run it in the database you want to explore (psql, pgAdmin, DBeaver, or your host's SQL\n-- editor), copy the one cell it returns, and paste it into Joinscope (Import, \"From a query\").\n-- Every schema except PostgreSQL's own is read; tables outside \"public\" keep their schema name.\n-- Partitions are shown as their parent table.\n\nWITH rels AS (\n  SELECT c.oid, n.nspname AS schema, c.relname AS name, c.relkind, c.reltuples,\n         COALESCE(pg_partition_root(c.oid), c.oid) AS root\n  FROM pg_class c\n  JOIN pg_namespace n ON n.oid = c.relnamespace\n  WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND n.nspname NOT LIKE 'pg_temp%'\n),\nroot_names AS (\n  SELECT r.oid, rr.schema, rr.name FROM rels r JOIN rels rr ON rr.oid = r.root\n)\nSELECT json_build_object(\n  'format', 'joinscope-catalogue', 'version', 1, 'dialect', 'postgres', 'database', current_database(),\n  'tables', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name,\n      'rows', (SELECT GREATEST(SUM(GREATEST(p.reltuples, 0)), 0)::bigint FROM rels p WHERE p.root = r.oid AND p.relkind = 'r'),\n      'comment', obj_description(r.oid, 'pg_class')) ORDER BY r.schema, r.name), '[]')\n    FROM rels r WHERE r.relkind IN ('r', 'p') AND r.root = r.oid),\n  'columns', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'column', a.attname, 'position', a.attnum,\n      'type', format_type(a.atttypid, a.atttypmod), 'nullable', NOT a.attnotnull,\n      'default', pg_get_expr(d.adbin, d.adrelid), 'comment', col_description(r.oid, a.attnum),\n      'auto', a.attidentity <> '' OR COALESCE(pg_get_expr(d.adbin, d.adrelid), '') LIKE 'nextval(%',\n      'generated', a.attgenerated <> '') ORDER BY r.schema, r.name, a.attnum), '[]')\n    FROM rels r\n    JOIN pg_attribute a ON a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped\n    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum\n    WHERE r.relkind IN ('r', 'p') AND r.root = r.oid),\n  'primary_keys', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'column', a.attname, 'position', k.pos)), '[]')\n    FROM pg_constraint con\n    JOIN rels r ON r.oid = con.conrelid AND r.root = r.oid\n    CROSS JOIN LATERAL unnest(con.conkey) WITH ORDINALITY AS k(attnum, pos)\n    JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum\n    WHERE con.contype = 'p'),\n  'foreign_keys', (SELECT COALESCE(json_agg(json_build_object(\n      'name', con.conname, 'schema', src.schema, 'table', src.name, 'column', a.attname, 'position', k.pos,\n      'ref_schema', dst.schema, 'ref_table', dst.name, 'ref_column', fa.attname,\n      'on_delete', CASE con.confdeltype WHEN 'c' THEN 'CASCADE' WHEN 'n' THEN 'SET NULL' WHEN 'd' THEN 'SET DEFAULT' WHEN 'r' THEN 'RESTRICT' ELSE 'NO ACTION' END,\n      'on_update', CASE con.confupdtype WHEN 'c' THEN 'CASCADE' WHEN 'n' THEN 'SET NULL' WHEN 'd' THEN 'SET DEFAULT' WHEN 'r' THEN 'RESTRICT' ELSE 'NO ACTION' END)), '[]')\n    FROM pg_constraint con\n    JOIN root_names src ON src.oid = con.conrelid\n    JOIN root_names dst ON dst.oid = con.confrelid\n    CROSS JOIN LATERAL unnest(con.conkey, con.confkey) WITH ORDINALITY AS k(attnum, refnum, pos)\n    JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum\n    JOIN pg_attribute fa ON fa.attrelid = con.confrelid AND fa.attnum = k.refnum\n    WHERE con.contype = 'f' AND con.conparentid = 0),\n  'indexes', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'name', ic.relname, 'unique', i.indisunique, 'partial', i.indpred IS NOT NULL,\n      'column', COALESCE(a.attname, pg_get_indexdef(i.indexrelid, k.pos::int, true)), 'position', k.pos)), '[]')\n    FROM pg_index i\n    JOIN rels r ON r.oid = i.indrelid AND r.root = r.oid\n    JOIN pg_class ic ON ic.oid = i.indexrelid\n    CROSS JOIN LATERAL unnest(i.indkey::int2[]) WITH ORDINALITY AS k(attnum, pos)\n    LEFT JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum AND k.attnum > 0\n    WHERE NOT i.indisprimary AND k.pos <= i.indnkeyatts),\n  'views', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'name', r.name, 'sql', pg_get_viewdef(r.oid, true)) ORDER BY r.schema, r.name), '[]')\n    FROM rels r WHERE r.relkind IN ('v', 'm')),\n  'triggers', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'name', t.tgname,\n      'timing', CASE WHEN t.tgtype & 2 <> 0 THEN 'BEFORE' WHEN t.tgtype & 64 <> 0 THEN 'INSTEAD OF' ELSE 'AFTER' END,\n      'event', concat_ws(' OR ', CASE WHEN t.tgtype & 4 <> 0 THEN 'INSERT' END, CASE WHEN t.tgtype & 8 <> 0 THEN 'DELETE' END,\n                         CASE WHEN t.tgtype & 16 <> 0 THEN 'UPDATE' END, CASE WHEN t.tgtype & 32 <> 0 THEN 'TRUNCATE' END),\n      'body', pg_get_triggerdef(t.oid, true))), '[]')\n    FROM pg_trigger t\n    JOIN rels r ON r.oid = t.tgrelid AND r.root = r.oid\n    WHERE NOT t.tgisinternal)\n) AS joinscope;\n",
  "sqlite": "-- Joinscope catalogue query for SQLite 3.38+ (also Cloudflare D1, Turso and other SQLite consoles)\n--\n-- Read-only: it reads the database's own description (sqlite_master and the pragma\n-- functions), never your data. Have the database file? Drop it on Joinscope instead:\n-- it is opened in your browser and nothing is uploaded. Use this query when you only\n-- have a console, then copy the one cell it returns and paste it into Joinscope\n-- (Import, \"From a query\").\n\nSELECT json_object(\n  'format', 'joinscope-catalogue', 'version', 1, 'dialect', 'sqlite',\n  'tables', json((SELECT json_group_array(json_object('table', m.name))\n    FROM sqlite_master m WHERE m.type = 'table' AND m.name NOT LIKE 'sqlite_%')),\n  'columns', json((SELECT json_group_array(json_object(\n      'table', m.name, 'column', p.name, 'position', p.cid + 1, 'type', p.type,\n      'nullable', json(CASE WHEN p.\"notnull\" = 0 AND p.pk = 0 THEN 'true' ELSE 'false' END),\n      'default', p.dflt_value,\n      'auto', json(CASE WHEN p.pk = 1 AND upper(p.type) = 'INTEGER'\n                         AND (SELECT COUNT(*) FROM pragma_table_info(m.name) k WHERE k.pk > 0) = 1 THEN 'true' ELSE 'false' END),\n      'generated', json(CASE WHEN p.hidden IN (2, 3) THEN 'true' ELSE 'false' END)))\n    FROM sqlite_master m, pragma_table_xinfo(m.name) p\n    WHERE m.type = 'table' AND m.name NOT LIKE 'sqlite_%')),\n  'primary_keys', json((SELECT json_group_array(json_object('table', m.name, 'column', p.name, 'position', p.pk))\n    FROM sqlite_master m, pragma_table_info(m.name) p\n    WHERE m.type = 'table' AND p.pk > 0 AND m.name NOT LIKE 'sqlite_%')),\n  'foreign_keys', json((SELECT json_group_array(json_object(\n      'id', f.id, 'table', m.name, 'column', f.\"from\", 'position', f.seq + 1,\n      'ref_table', f.\"table\", 'ref_column', f.\"to\", 'on_delete', f.on_delete, 'on_update', f.on_update))\n    FROM sqlite_master m, pragma_foreign_key_list(m.name) f\n    WHERE m.type = 'table')),\n  'indexes', json((SELECT json_group_array(json_object(\n      'table', m.name, 'name', il.name, 'unique', json(CASE WHEN il.\"unique\" THEN 'true' ELSE 'false' END),\n      'column', ii.name, 'position', ii.seqno + 1))\n    FROM sqlite_master m, pragma_index_list(m.name) il, pragma_index_info(il.name) ii\n    WHERE m.type = 'table' AND il.origin <> 'pk')),\n  'views', json((SELECT json_group_array(json_object('name', name, 'sql', sql))\n    FROM sqlite_master WHERE type = 'view')),\n  'triggers', json((SELECT json_group_array(json_object('name', name, 'table', tbl_name, 'body', sql))\n    FROM sqlite_master WHERE type = 'trigger'))\n) AS joinscope;\n",
  "sqlserver": "-- Joinscope catalogue query for SQL Server 2016+ and Azure SQL\n--\n-- Read-only: it reads the database's catalogue (sys views), never your data.\n-- Run it on the database you want to explore, copy the one cell it returns, and paste\n-- it into Joinscope (Import, \"From a query\").\n--\n-- SSMS copies at most 65,535 characters of a cell (Results to Text and Results to File\n-- cut it shorter): enough for a few dozen tables. For a bigger database, run it with\n-- sqlcmd, which prints the whole cell, or script the database instead (Generate Scripts):\n--   sqlcmd -S server -d database -E -y 0 -f 65001 -i sqlserver.sql -o schema.json\n-- (-E signs in as you; use -U user instead to be asked for a password. -f 65001 writes UTF-8.)\n\nSET NOCOUNT ON;\n\nSELECT (\n  SELECT 'joinscope-catalogue' AS [format], 1 AS [version], 'sqlserver' AS [dialect], DB_NAME() AS [database],\n    (SELECT s.name AS [schema], t.name AS [table],\n        (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = t.object_id AND p.index_id IN (0, 1)) AS [rows],\n        CAST(ep.value AS nvarchar(max)) AS [comment]\n      FROM sys.tables t\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      LEFT JOIN sys.extended_properties ep ON ep.class = 1 AND ep.major_id = t.object_id AND ep.minor_id = 0 AND ep.name = 'MS_Description'\n      WHERE t.is_ms_shipped = 0 AND t.name <> 'sysdiagrams'\n      FOR JSON PATH) AS [tables],\n    (SELECT s.name AS [schema], t.name AS [table], c.name AS [column], c.column_id AS [position],\n        CASE\n          WHEN ty.is_user_defined = 1 THEN ty.name\n          WHEN ty.name IN ('varchar', 'char', 'varbinary', 'binary')\n            THEN ty.name + '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length AS varchar(10)) END + ')'\n          WHEN ty.name IN ('nvarchar', 'nchar')\n            THEN ty.name + '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length / 2 AS varchar(10)) END + ')'\n          WHEN ty.name IN ('decimal', 'numeric')\n            THEN ty.name + '(' + CAST(c.precision AS varchar(10)) + ',' + CAST(c.scale AS varchar(10)) + ')'\n          WHEN ty.name IN ('datetime2', 'time', 'datetimeoffset')\n            THEN ty.name + '(' + CAST(c.scale AS varchar(10)) + ')'\n          ELSE ty.name\n        END AS [type],\n        c.is_nullable AS [nullable], dc.definition AS [default], CAST(ep.value AS nvarchar(max)) AS [comment],\n        c.is_identity AS [auto], c.is_computed AS [generated]\n      FROM sys.columns c\n      JOIN sys.tables t ON t.object_id = c.object_id\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      JOIN sys.types ty ON ty.user_type_id = c.user_type_id\n      LEFT JOIN sys.default_constraints dc ON dc.parent_object_id = c.object_id AND dc.parent_column_id = c.column_id\n      LEFT JOIN sys.extended_properties ep ON ep.class = 1 AND ep.major_id = c.object_id AND ep.minor_id = c.column_id AND ep.name = 'MS_Description'\n      WHERE t.is_ms_shipped = 0 AND t.name <> 'sysdiagrams'\n      FOR JSON PATH) AS [columns],\n    (SELECT s.name AS [schema], t.name AS [table], c.name AS [column], ic.key_ordinal AS [position]\n      FROM sys.indexes i\n      JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.key_ordinal > 0\n      JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id\n      JOIN sys.tables t ON t.object_id = i.object_id\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      WHERE i.is_primary_key = 1 AND t.is_ms_shipped = 0 AND t.name <> 'sysdiagrams'\n      FOR JSON PATH) AS [primary_keys],\n    (SELECT fk.name AS [name], s.name AS [schema], t.name AS [table], c.name AS [column], fkc.constraint_column_id AS [position],\n        rs.name AS [ref_schema], rt.name AS [ref_table], rc.name AS [ref_column],\n        fk.delete_referential_action_desc AS [on_delete], fk.update_referential_action_desc AS [on_update]\n      FROM sys.foreign_keys fk\n      JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id\n      JOIN sys.tables t ON t.object_id = fk.parent_object_id\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      JOIN sys.columns c ON c.object_id = fkc.parent_object_id AND c.column_id = fkc.parent_column_id\n      JOIN sys.tables rt ON rt.object_id = fk.referenced_object_id\n      JOIN sys.schemas rs ON rs.schema_id = rt.schema_id\n      JOIN sys.columns rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id\n      WHERE t.is_ms_shipped = 0 AND t.name <> 'sysdiagrams'\n      FOR JSON PATH) AS [foreign_keys],\n    (SELECT s.name AS [schema], t.name AS [table], i.name AS [name], i.is_unique AS [unique], i.type_desc AS [type],\n        i.has_filter AS [partial], c.name AS [column], ic.key_ordinal AS [position]\n      FROM sys.indexes i\n      JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.key_ordinal > 0\n      JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id\n      JOIN sys.tables t ON t.object_id = i.object_id\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      WHERE i.is_primary_key = 0 AND i.is_hypothetical = 0 AND i.type IN (1, 2, 4) AND t.is_ms_shipped = 0 AND t.name <> 'sysdiagrams'\n      FOR JSON PATH) AS [indexes],\n    (SELECT s.name AS [schema], v.name AS [name], OBJECT_DEFINITION(v.object_id) AS [sql]\n      FROM sys.views v\n      JOIN sys.schemas s ON s.schema_id = v.schema_id\n      WHERE v.is_ms_shipped = 0\n      FOR JSON PATH) AS [views],\n    (SELECT s.name AS [schema], t.name AS [table], tr.name AS [name],\n        CASE WHEN tr.is_instead_of_trigger = 1 THEN 'INSTEAD OF' ELSE 'AFTER' END AS [timing],\n        STUFF((SELECT ' OR ' + te.type_desc FROM sys.trigger_events te WHERE te.object_id = tr.object_id ORDER BY te.type FOR XML PATH('')), 1, 4, '') AS [event],\n        OBJECT_DEFINITION(tr.object_id) AS [body]\n      FROM sys.triggers tr\n      JOIN sys.tables t ON t.object_id = tr.parent_id\n      JOIN sys.schemas s ON s.schema_id = t.schema_id\n      WHERE tr.parent_class = 1 AND tr.is_ms_shipped = 0\n      FOR JSON PATH) AS [triggers]\n  FOR JSON PATH, WITHOUT_ARRAY_WRAPPER\n) AS joinscope;\n"
};
  if (typeof module !== 'undefined' && module.exports) module.exports = queries;
  else root.JOINSCOPE_QUERIES = queries;
})(this);
